-- Versioned drama strategy, characters and episode outlines. Manual after 118.
SET search_path TO new_design, public;
CREATE TABLE drama_stage_entities(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES drama_projects(id),stage_kind text NOT NULL CHECK(stage_kind IN('strategy','character','episode')),logical_order integer,revision integer NOT NULL DEFAULT 0,adopted_version_id uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,id),UNIQUE(project_id,stage_kind,logical_order));
CREATE TABLE drama_stage_versions(id uuid PRIMARY KEY,project_id uuid NOT NULL,entity_id uuid NOT NULL,version integer NOT NULL CHECK(version>0),source_version_id uuid NOT NULL,upstream_version_ids jsonb NOT NULL CHECK(jsonb_typeof(upstream_version_ids)='array'),content jsonb NOT NULL CHECK(jsonb_typeof(content)='object'),source_kind text NOT NULL CHECK(source_kind IN('manual','ai_candidate')),request_key uuid NOT NULL UNIQUE,input_hash char(64) NOT NULL CHECK(input_hash ~ '^[a-f0-9]{64}$'),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(entity_id,version),UNIQUE(entity_id,id),FOREIGN KEY(project_id,entity_id) REFERENCES drama_stage_entities(project_id,id),FOREIGN KEY(project_id,source_version_id) REFERENCES drama_source_versions(project_id,id));
ALTER TABLE drama_stage_entities ADD CONSTRAINT drama_stage_adopted_fk FOREIGN KEY(id,adopted_version_id) REFERENCES drama_stage_versions(entity_id,id);
CREATE TABLE drama_stage_adoptions(id uuid PRIMARY KEY,project_id uuid NOT NULL,entity_id uuid NOT NULL,version_id uuid NOT NULL,revision integer NOT NULL CHECK(revision>0),request_key uuid NOT NULL UNIQUE,input_hash char(64) NOT NULL CHECK(input_hash ~ '^[a-f0-9]{64}$'),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(entity_id,revision),FOREIGN KEY(project_id,entity_id) REFERENCES drama_stage_entities(project_id,id),FOREIGN KEY(entity_id,version_id) REFERENCES drama_stage_versions(entity_id,id));
CREATE TRIGGER drama_stage_versions_immutable BEFORE UPDATE OR DELETE ON drama_stage_versions FOR EACH ROW EXECUTE FUNCTION guard_drama_history();
CREATE TRIGGER drama_stage_adoptions_immutable BEFORE UPDATE OR DELETE ON drama_stage_adoptions FOR EACH ROW EXECUTE FUNCTION guard_drama_history();
